  const interactiveGuideSteps={
    doctor:[guided('Review a clinical item','复核一项临床记录','The doctor overview brings pending imported records and AI-assisted summaries into one queue.','医生概览会集中展示待确认的导入记录和 AI 辅助摘要。','Select Approve or Reject only after checking the patient and source.','核对患者与来源后，再点击“通过”或“驳回”。','[data-action="review-approve"]','Use this decision button','操作这个审核按钮','The item leaves the pending queue and an audit event is recorded.','该项目移出待复核队列，并写入审计记录。','overview'),guided('Send a consultation message','发送问诊消息','The consultation room keeps doctor, patient, and family in the same conversation.','问诊室让医生、患者和家属处于同一会话。','Enter a short message here, then use the Send button.','在这里输入简短消息，然后点击“发送消息”。','#chat-form textarea','Type here','在这里输入','The message appears in the transcript and a simulated reply follows.','消息进入会话记录，随后收到模拟回复。','consultation')],
    patient:[guided('Record today’s measurement','记录今日测量','Today’s task list connects each due measurement to its entry workflow.','今日任务会把待测指标直接连接到录入流程。','Select Record on the highlighted blood-pressure task.','点击高亮血压任务上的“记录”。','[data-action="vital"]','Open this action','打开这个操作','A structured blood-pressure form opens for confirmation.','系统打开结构化血压录入表单。','today'),guided('Send a consultation message','发送问诊消息','You can describe symptoms to the doctor while an authorized family member follows the same conversation.','你可以向医生描述症状，已授权家属可同步查看会话。','Enter the symptom or reply in this field, then send it.','在此输入症状或回复，然后发送。','#chat-form textarea','Type here','在这里输入','The message is added to the consultation transcript.','消息会加入问诊记录。','consultation')],
    family:[guided('Complete a shared care task','完成共享照护任务','The family schedule shows unfinished medication and measurement work for the selected person.','家庭日程会显示当前家人未完成的用药和测量任务。','Use the highlighted task button after the care action is actually complete.','照护操作实际完成后，点击高亮的任务按钮。','[data-action="complete"]','Confirm this task','确认这个任务','Every caregiver can see the updated completion state.','所有照护者都能看到更新后的完成状态。','care'),guided('Add a handover','新增照护交接','Handover notes tell the next caregiver exactly what remains.','交接记录会明确告诉下一位照护者还有什么待办。','Open the highlighted handover action and record only necessary care information.','打开高亮的交接操作，只记录必要的照护信息。','[data-action="handover"]','Open handover','打开交接','The note joins the shared family timeline.','记录会进入家庭共享时间线。','care')],
    admin:[guided('Change an account status','调整账号状态','User management separates account status from access to patient data.','用户管理将账号状态与患者数据授权分开。','Use the highlighted status button only after verifying the user and role.','核对用户和角色后，再使用高亮的状态按钮。','[data-action="toggle-user"]','Review this control','核对这个控件','The account status changes and the action is auditable.','账号状态更新，并留下审计记录。','users'),guided('Configure the platform identity','配置平台身份','Brand settings control the name, organization, logo, background, and ownership text.','品牌设置统一管理平台名称、机构、Logo、背景与所有权文字。','Edit the highlighted platform-name field and save the complete form.','修改高亮的平台名称字段，再保存完整表单。','#branding-form input[name="platformName"]','Edit this field','修改这个字段','The new identity is applied across the demo.','新的平台身份会应用到整个演示。','branding')]
  };
  interactiveGuideSteps.nurse=[guided('Follow up authorized actions','跟进已授权事项','Nursing requires an active assignment and a separate CARE_PLAN grant.','护理访问需要有效分配及独立 CARE_PLAN 授权。','Check the nursing queue; record a follow-up without changing clinical instructions.','查看护理队列，记录跟进但不改变临床说明。','[data-page="nursing"]','Open nursing queue','打开护理队列','Follow-up stays separate from doctor review.','跟进与医生复核保持独立。','nursing')];
  const interactiveGuideCommon=[guided('Run a real feature demonstration','执行真实功能演示','The care journey contains working demonstrations for all supported medical workflows.','照护全流程包含全部医疗场景的可操作演示。','Click the highlighted action to update local state and create an audit event.','点击高亮操作，更新本地状态并生成审计事件。','[data-action="module-action"]','Try this button','试试这个按钮','The card changes to completed and the event appears in the audit log.','卡片变为已执行，事件写入审计日志。','journey'),guided('Confirm the current patient','确认当前患者','Every clinical action uses the patient selected in the header.','每项临床操作都使用顶部选中的患者。','Open this selector and verify the name before recording information.','录入信息前，打开选择器并核对姓名。','#patient','Check this selector','核对这个选择器','The selected patient remains visible throughout the workspace.','当前患者会持续显示在工作台顶部。'),guided('Follow the platform language','跟随平台语言','The guide always uses the same language as the current platform interface.','指引始终使用当前平台界面的语言。','Use this language control when you need to switch the whole demo.','需要切换整个演示语言时，使用这个语言入口。','.language-link','Language follows here','语言跟随这里','The page and every guide step switch together.','页面和每一步指引会同步切换语言。')];
  let guideIndex=0, guideReturnFocus, guidePositionTimer, guidePositionVersion=0;
  function currentGuide(){return [...interactiveGuideSteps[state.role],...interactiveGuideCommon].filter(step=>!step.path||Object.hasOwn(copy[state.role].nav,step.path)).map(guideMeta)}
  function guideMeta(step) {
    if (step.selector === '[data-action="review-approve"]' && !state.reviews.some(item => item.status === 'pending')) {
      return guided('No clinical items awaiting review','暂无待复核项目',
        'The pending review queue is empty, so no Approve or Reject button is available.','待复核队列为空，因此没有“通过”或“驳回”按钮。',
        'Review the empty queue, then continue the guide.','查看空队列，然后继续指引。',
        '.columns .empty','Review this queue','查看这个队列',
        'There is no review decision to make in this step.','此步骤暂无需要作出的复核决定。',step.path);
    }
    if (step.selector === '[data-action="complete"]' && !p().tasks.some(task => !task.done && task.type !== 'vital')) {
      return guided('No one-click care task is pending','暂无可直接完成的照护任务',
        'There is no Mark taken or Complete button for the selected patient. Measurements may still need to be recorded.','当前患者没有“标记已服”或“完成”按钮，测量仍可能需要记录。',
        'Check the task statuses here, then continue the guide.','在这里查看任务状态，然后继续指引。',
        '.care-task-columns','Check these task statuses','查看这些任务状态',
        'Remaining measurements, if any, use Record health.','如仍有待测指标，可使用“记录健康”。',step.path);
    }
    if (step.selector !== '#chat-form textarea' || M.currentConsultation(state)) return step;
    return guided('No consultation for this patient','当前患者暂无问诊会话',
      'The selected patient has no demo conversation, so no message field is available.','当前患者暂无演示会话，因此没有消息输入框。',
      'Verify the selected patient here, then continue the guide.','在这里核对当前患者，然后继续指引。',
      '#patient','Check this selector','核对这个选择器',
      'Viewing and sending messages requires a patient with an existing conversation.','选择已有会话的患者后，才可查看和发送消息。',step.path);
  }
  function positionGuide(target){document.querySelector('.guide-target')?.classList.remove('guide-target');target.classList.add('guide-target');const rect=target.getBoundingClientRect(),card=$('guide-popover'),anchor=$('guide-anchor'),width=Math.min(370,innerWidth-24),height=card.offsetHeight||260,gap=20;let placement,left,top,anchorLeft,anchorTop;if(innerWidth<720){const cardBelow=rect.top<innerHeight/2;placement=cardBelow?'top':'bottom';left=12;top=cardBelow?innerHeight-height-12:12;anchorLeft=rect.left+rect.width/2;anchorTop=cardBelow?rect.bottom:rect.top;}else if(rect.right+gap+width<innerWidth){placement='right';left=rect.right+gap;top=rect.top+rect.height/2-height/2;anchorLeft=rect.right;anchorTop=rect.top+rect.height/2;}else if(rect.left-width-gap>0){placement='left';left=rect.left-width-gap;top=rect.top+rect.height/2-height/2;anchorLeft=rect.left;anchorTop=rect.top+rect.height/2;}else if(rect.bottom+gap+height<innerHeight){placement='top';left=rect.left+rect.width/2-width/2;top=rect.bottom+gap;anchorLeft=rect.left+rect.width/2;anchorTop=rect.bottom;}else{placement='bottom';left=rect.left+rect.width/2-width/2;top=rect.top-height-gap;anchorLeft=rect.left+rect.width/2;anchorTop=rect.top;}card.className=`guide-popover guide-popover--${placement}`;card.style.width=`${width}px`;card.style.setProperty('left',`${Math.max(12,Math.min(left,innerWidth-width-12))}px`,'important');card.style.setProperty('top',`${Math.max(12,Math.min(top,innerHeight-height-12))}px`,'important');Object.assign(anchor.style,{left:`${anchorLeft}px`,top:`${anchorTop}px`});}
  function showGuideStep(focusGuide=false){clearTimeout(guidePositionTimer);const positionVersion=++guidePositionVersion;document.querySelector('.guide-target')?.classList.remove('guide-target');const steps=currentGuide();guideIndex=Math.max(0,Math.min(guideIndex,steps.length-1));const step=steps[guideIndex];if(step.path&&page()!==step.path){location.hash=step.path;render();}$('guide-progress').textContent=tx('GUIDED TOUR','交互指引');$('guide-count').textContent=`${guideIndex+1} / ${currentGuide().length}`;$('guide-title').textContent=step.title;$('guide-description').textContent=step.description;$('guide-action').textContent=step.action;$('guide-result').textContent=step.result;$('guide-gesture').textContent=step.gesture;$('guide-previous').disabled=guideIndex===0;$('guide-next').textContent=guideIndex===currentGuide().length-1?'✓':'›';$('guide-next').setAttribute('aria-label',guideIndex===currentGuide().length-1?tx('Finish guide','完成指引'):tx('Confirm step and continue','确认本步骤并继续'));if(focusGuide)$('guide-title').focus({preventScroll:true});guidePositionTimer=setTimeout(()=>{if($('guide-tour').hidden||positionVersion!==guidePositionVersion)return;const target=document.querySelector(step.selector)||$('content');target.scrollIntoView?.({block:'center',behavior:scrollBehavior()});positionGuide(target)},120);}
  function refreshGuide() {
    if (!$('guide-tour').hidden) showGuideStep();
  }
  function closeGuide() {
    clearTimeout(guidePositionTimer);
    guidePositionVersion++;
    $('guide-tour').hidden = true;
    document.querySelector('.guide-target')?.classList.remove('guide-target');
    (guideReturnFocus?.isConnected ? guideReturnFocus : $('guide-start')).focus({preventScroll:true});
  }
  function openGuide() {
    guideReturnFocus = document.activeElement;
    guideIndex = 0; $('guide-tour').hidden = false; showGuideStep(true);
  }
  document.addEventListener('keydown', event => {
    if(event.key === 'Escape' && !$('guide-tour').hidden && !document.querySelector('dialog[open]')) {
      event.preventDefault(); closeGuide();
    }
  });
  const button = (label, act, secondary=false, data='') => `<button class="button${secondary?' secondary':''}" data-action="${act}" ${data}>${label}</button>`;
  function toast(message) { const el=$('toast'); el.textContent=message; el.hidden=false; clearTimeout(toastTimer); toastTimer=setTimeout(()=>{el.hidden=true;},3200); }
  function page() { const key=location.hash.slice(1), nav=copy[state.role].nav; return Object.hasOwn(nav,key)?key:copy[state.role].start; }
  function heading(kicker,title,subtitle,art='care-moments-small.webp',actions='') { return `<header class="page-heading"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${subtitle}</p>${actions?`<div class="heading-actions">${actions}</div>`:''}</div><img class="heading-art" src="assets/${art}" alt="" width="180" height="120"></header>`; }
  function risk(value) { return `<span class="tag risk-${value}">${value==='critical'?tx('Needs review','需关注'):value==='watch'?tx('Watch','观察'):tx('Stable','稳定')}</span>`; }
  function patientAppointments() {
    const now = new Date();
    const today = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;
    return state.appointments.filter(item => item.patientId === state.patientId && item.date >= today)
      .sort((a, b) => `${a.date} ${a.time}`.localeCompare(`${b.date} ${b.time}`));
  }
  function patientNote() {
    const note = state.notes.filter(item => item.patientId === state.patientId)
      .sort((a, b) => b.date.localeCompare(a.date))[0];
    return note ? `<div class="note"><span class="avatar light">${tx('DR','医')}</span><div><b>${esc(l(note.author))}</b><p>${esc(l(note.text))}</p></div></div>`
      : `<p class="empty">${tx('No clinical note for this patient.','当前患者暂无医生笔记。')}</p>`;
  }
  function stats() { const latest=p().records.at(-1), done=p().tasks.filter(t=>t.done).length, pending=state.reviews.filter(r=>r.status==='pending'&&(state.role==='doctor'||r.patientId===state.patientId)).length, appointment=patientAppointments()[0]; return `<section class="stats"><article><span>${tx('Today’s tasks','今日任务')}</span><strong>${done}<small> / ${p().tasks.length}</small></strong><p>${tx('Care plan progress','照护计划进度')}</p></article><article><span>${tx('Latest blood pressure','最近血压')}</span><strong>${latest.systolic}<small> / ${latest.diastolic}</small></strong><p>mmHg · ${latest.date}</p></article><article><span>${tx('Pending clinical reviews','待临床复核')}</span><strong>${pending}<small> ${tx(pending===1?'item':'items','项')}</small></strong><p>${tx('Records and AI summaries','记录与 AI 摘要')}</p></article><article><span>${tx('Next appointment','下次复诊')}</span>${appointment?`<strong>${esc(appointment.date.slice(5))}<small> ${esc(appointment.time)}</small></strong><p>${esc(l(appointment.clinic))}</p>`:`<p>${tx('No upcoming appointment','暂无复诊安排')}</p>`}</article></section>`; }
  function tasks(filter) { const rows=p().tasks.filter(t=>!filter||(filter==='care'?t.type!=='medication':t.type===filter)).sort((a,b)=>Number(a.done)-Number(b.done)); return `<div class="task-list">${rows.map(t=>`<article class="task ${t.done?'done':''}"><span class="time">${t.time}</span><span class="task-mark">${t.done?'✓':'◷'}</span><div class="task-copy"><b>${l(t.title)}</b><small>${l(t.detail)}</small></div>${t.done?`<span class="tag">${tx('Completed','已完成')}</span>`:button(t.type==='medication'?tx('Mark taken','标记已服'):t.type==='vital'?tx('Record','记录'):tx('Complete','完成'),t.type==='vital'?'vital':'complete',true,`data-id="${t.id}"`)}</article>`).join('')}</div>`; }
  function chart(width = 700) {
    width = Number.isFinite(width) && width > 90 ? width : 700;
    const end = new Date(), start = new Date(end);
    start.setDate(start.getDate() - range + 1);
    const dateKey = date => `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
    const rows = p().records.filter(row => row.date >= dateKey(start) && row.date <= dateKey(end))
      .sort((a,b) => `${a.date} ${a.time}`.localeCompare(`${b.date} ${b.time}`));
    if (!rows.length) return `<div class="empty"><p>${tx('No readings in this period.','此时间段暂无读数。')}</p></div>`;
    const values = rows.flatMap(row => [row.systolic, row.diastolic]);
    const minimum = Math.floor(Math.min(50,...values)/10)*10-10;
    const maximum = Math.ceil(Math.max(160,...values)/10)*10+10;
    const x = index => 48+index*(width-90)/Math.max(1,rows.length-1);
    const y = value => 210-(value-minimum)/(maximum-minimum)*175;
    const ticks = Array.from({length:5},(_,index) => Math.round(minimum+(maximum-minimum)*index/4));
    const line = key => rows.map((row,index) => `${x(index)},${y(row[key])}`).join(' ');
    return `<div class="chart-legend"><span>● ${tx('Systolic','收缩压')}</span><span>● ${tx('Diastolic','舒张压')}</span><small>mmHg · ${tx('fictional data','虚构数据')}</small></div><svg class="chart" viewBox="0 0 ${width} 240" role="img" aria-label="${tx('Blood pressure trend','血压趋势')}"><g class="grid-lines">${ticks.map(value => `<line x1="48" y1="${y(value)}" x2="${width-42}" y2="${y(value)}"/><text x="8" y="${y(value)+4}">${value}</text>`).join('')}</g><polyline class="line-primary" points="${line('systolic')}"/><polyline class="line-secondary" points="${line('diastolic')}"/>${rows.map((row,index) => `<circle cx="${x(index)}" cy="${y(row.systolic)}" r="3.5" fill="#267266"><title>${row.date} ${row.time}: ${row.systolic}/${row.diastolic}</title></circle>`).join('')}<g class="grid-lines"><text x="48" y="235">${rows[0].date.slice(5)}</text><text x="${width-42}" y="235" text-anchor="end">${rows.at(-1).date.slice(5)}</text></g></svg>`;
  }
  let cleanupChart = () => {}, redrawChart = () => {};
  function mountChart() {
    const host = document.querySelector('.chart-host');
    if (!host) return;
    let disposed = false, lastWidth;
    const redraw = () => {
      if (disposed || !host.isConnected) return;
      const width = host.getBoundingClientRect().width;
      if (!Number.isFinite(width) || width <= 90 || width === lastWidth) return;
      lastWidth = width;
      host.innerHTML = chart(width);
    };
    redrawChart = redraw;
    if (typeof window.ResizeObserver === 'function') {
      const observer = new window.ResizeObserver(redraw);
      observer.observe(host);
      cleanupChart = () => { disposed = true; redrawChart = () => {}; observer.disconnect(); };
    } else {
      window.addEventListener('resize', redraw);
      cleanupChart = () => { disposed = true; redrawChart = () => {}; window.removeEventListener('resize', redraw); };
    }
    redraw();
  }
  const rangeControl = () => `<div class="segmented"><button data-action="range" data-days="7" aria-pressed="${range===7}">${tx('7 days','7 天')}</button><button data-action="range" data-days="30" aria-pressed="${range===30}">${tx('30 days','30 天')}</button></div>`;
