  function reviewQueue() { const rows=state.reviews.filter(r=>r.status==='pending'); return rows.length?`<div class="review-list">${rows.map(r=>{const patient=state.patients.find(x=>x.id===r.patientId); return `<article class="review-card"><div><span class="eyebrow">${r.kind==='ai'?tx('AI-ASSISTED · REQUIRES CLINICIAN REVIEW','AI 辅助 · 须医生复核'):tx('IMPORTED RECORD','导入记录')}</span><h3>${l(patient.name)} · ${l(r.title)}</h3><p>${r.date} · ${tx('Extraction confidence','提取可信度')} ${r.confidence}%</p></div><div class="review-actions">${button(tx('Approve','通过'),'review-approve',true,`data-id="${r.id}"`)}${button(tx('Reject','驳回'),'review-reject',true,`data-id="${r.id}"`)}</div></article>`;}).join('')}</div>`:`<div class="empty"><b>${tx('Review queue cleared','复核队列已清空')}</b><p>${tx('There are no imported records or AI summaries waiting for a clinician.','暂无等待医生确认的导入记录或 AI 摘要。')}</p></div>`; }
  function doctorOverview() { return heading(tx('CLINICAL WORKSPACE','医生工作台'),tx('Start with what needs clinical attention','先处理真正需要临床关注的事项'),tx('Risk, review, and care-plan work are organized around assigned patients.','围绕已分配患者，集中处理风险、复核与照护计划。'),'health-journal-small.webp')+stats()+`<div class="columns"><section class="panel"><header class="panel-heading"><div><span class="eyebrow">${tx('PRIORITY','优先处理')}</span><h2>${tx('Clinical review queue','临床复核队列')}</h2></div><a href="#reviews">${tx('View all','查看全部')} →</a></header>${reviewQueue()}</section><section class="panel"><header class="panel-heading"><div><span class="eyebrow">${tx('SELECTED PATIENT','当前患者')}</span><h2>${l(p().name)}</h2></div>${risk(p().risk)}</header><p>${l(p().condition)}</p>${patientNote()}${button(tx('Create care plan','新建照护计划'),'plan')}</section></div>`; }
