  function reviews() { return heading(tx('CLINICAL SAFETY','临床安全'),tx('Review before information becomes clinical truth','先复核，再让信息进入临床记录'),tx('Imported records and AI-assisted analysis remain pending until a clinician decides.','导入记录与 AI 辅助分析必须经医生确认后生效。'),'records-care-small.webp')+`<section class="notice">${tx('AI output is decision support, not an autonomous diagnosis. Every decision is recorded in the full application.','AI 输出仅用于辅助决策，不会自动诊断；正式系统会记录每次复核。')}</section><section class="panel">${reviewQueue()}</section>`; }
